import { CommonModule } from '@angular/common';
import { Component } from '@angular/core';
import { FormsModule } from '@angular/forms';

interface ChatMessage {
  sender: 'assistant' | 'visitor';
  text: string;
  actionLabel?: string;
  actionHref?: string;
}

interface RatingBounds {
  minX: number;
  maxX: number;
  minY: number;
  maxY: number;
}

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  title = 'Angular Single Page Website';

  services = [
    { number: '01', title: 'Brand Identity', desc: 'Naming, logo systems and visual languages that make your brand unmistakable across every touchpoint.', icon: 'identity' },
    { number: '02', title: 'Product Design', desc: 'From first wireframe to polished interface — digital products that feel effortless and ship beautifully.', icon: 'product' },
    { number: '03', title: 'Design Strategy', desc: 'Positioning workshops and roadmaps that connect creative ambition to measurable business outcomes.', icon: 'strategy' }
  ];

  contact = {
    name: '',
    email: '',
    message: ''
  };

  submitted = false;

  ratingOffsetX = 0;
  ratingOffsetY = 0;
  isRatingDragging = false;
  private ratingPointerStartX = 0;
  private ratingPointerStartY = 0;
  private ratingDragStartX = 0;
  private ratingDragStartY = 0;
  private ratingDragBounds: RatingBounds = { minX: 0, maxX: 0, minY: 0, maxY: 0 };

  isChatOpen = false;
  chatInput = '';
  chatSuggestions = ['What services do you offer?', 'How do I start a project?'];
  chatMessages: ChatMessage[] = [
    {
      sender: 'assistant',
      text: 'Hello! I’m the Atelier Horizon assistant. Ask me about our services, process or getting started.'
    }
  ];

  onSubmit() {
    this.submitted = true;
  }

  startRatingDrag(event: PointerEvent) {
    if (event.button !== 0) {
      return;
    }

    const card = event.currentTarget as HTMLElement;
    card.setPointerCapture(event.pointerId);
    this.isRatingDragging = true;
    this.ratingPointerStartX = event.clientX;
    this.ratingPointerStartY = event.clientY;
    this.ratingDragStartX = this.ratingOffsetX;
    this.ratingDragStartY = this.ratingOffsetY;
    this.ratingDragBounds = this.getRatingBounds(card);
  }

  moveRatingDrag(event: PointerEvent) {
    if (!this.isRatingDragging) {
      return;
    }

    this.applyRatingOffset(
      this.ratingDragStartX + event.clientX - this.ratingPointerStartX,
      this.ratingDragStartY + event.clientY - this.ratingPointerStartY,
      this.ratingDragBounds
    );
  }

  endRatingDrag() {
    this.isRatingDragging = false;
  }

  moveRatingCardWithKeyboard(event: KeyboardEvent) {
    const movement = 12;
    const directions: Record<string, [number, number]> = {
      ArrowLeft: [-movement, 0],
      ArrowRight: [movement, 0],
      ArrowUp: [0, -movement],
      ArrowDown: [0, movement]
    };
    const direction = directions[event.key];

    if (!direction) {
      return;
    }

    event.preventDefault();
    this.setRatingOffset(
      event.currentTarget as HTMLElement,
      this.ratingOffsetX + direction[0],
      this.ratingOffsetY + direction[1]
    );
  }

  private setRatingOffset(card: HTMLElement, x: number, y: number) {
    this.applyRatingOffset(x, y, this.getRatingBounds(card));
  }

  private getRatingBounds(card: HTMLElement): RatingBounds {
    const parent = card.parentElement;
    if (!parent) {
      return this.ratingDragBounds;
    }

    const parentBounds = parent.getBoundingClientRect();
    const cardBounds = card.getBoundingClientRect();
    const baseLeft = cardBounds.left - this.ratingOffsetX;
    const baseTop = cardBounds.top - this.ratingOffsetY;
    return {
      minX: Math.min(0, parentBounds.left - baseLeft),
      maxX: parentBounds.right - cardBounds.width - baseLeft,
      minY: Math.min(0, parentBounds.top - baseTop),
      maxY: parentBounds.bottom - cardBounds.height - baseTop
    };
  }

  private applyRatingOffset(x: number, y: number, bounds: RatingBounds) {
    this.ratingOffsetX = Math.min(bounds.maxX, Math.max(bounds.minX, x));
    this.ratingOffsetY = Math.min(bounds.maxY, Math.max(bounds.minY, y));
  }

  sendChatMessage(message = this.chatInput) {
    const text = message.trim();
    if (!text) {
      return;
    }

    this.chatMessages.push({ sender: 'visitor', text });
    this.chatInput = '';
    this.chatSuggestions = [];
    this.chatMessages.push(this.getAssistantReply(text));
  }

  private getAssistantReply(message: string): ChatMessage {
    const question = message.toLowerCase();

    if (/identity|branding|brand|product|strategy|service|design/.test(question)) {
      return {
        sender: 'assistant',
        text: 'We bring brand identity, product design and design strategy together in one small team.',
        actionLabel: 'Explore our services',
        actionHref: '#services'
      };
    }

    if (/start|begin|project|contact|email|call|talk/.test(question)) {
      return {
        sender: 'assistant',
        text: 'Tell us a little about your goals using the contact form. The studio replies within two working days.',
        actionLabel: 'Contact the studio',
        actionHref: '#contact'
      };
    }

    if (/process|how.*work|approach/.test(question)) {
      return {
        sender: 'assistant',
        text: 'We start with clarity and research, then shape and test the right direction together. The same small team stays with your project from first conversation through delivery.',
        actionLabel: 'About the studio',
        actionHref: '#about'
      };
    }

    if (/where|location|located|address|amsterdam/.test(question)) {
      return {
        sender: 'assistant',
        text: 'Our studio is at Prinsengracht 402 in Amsterdam. We work with brands around the world.'
      };
    }

    if (/price|pricing|cost|budget|fee/.test(question)) {
      return {
        sender: 'assistant',
        text: 'Project costs depend on the scope. Share a little about what you have in mind and we can discuss the right fit.',
        actionLabel: 'Start a conversation',
        actionHref: '#contact'
      };
    }

    return {
      sender: 'assistant',
      text: 'I can help with our services, process, location or getting started. For anything else, send the studio a note.',
      actionLabel: 'Contact the studio',
      actionHref: '#contact'
    };
  }
}

<nav class="site-header" aria-label="Main navigation">
  <div class="container nav-inner">
    <a class="brand" href="#home" aria-label="Atelier Horizon home">
      <span class="brand-mark">Ah</span>
      <span class="brand-name">Atelier <em>Horizon</em></span>
    </a>
    <ul class="nav-links">
      <li><a class="active" href="#home">Home</a></li>
      <li><a href="#about">About</a></li>
      <li><a href="#services">Services</a></li>
      <li><a href="#contact">Contact</a></li>
    </ul>
    <a class="button button-small" href="#contact">Get Started</a>
  </div>
</nav>

<main>
  <header id="home" class="hero">
    <div class="container hero-layout">
      <div class="hero-copy">
        <p class="eyebrow"><span></span> Independent design studio</p>
        <h1>We give brands <em>clarity</em>, character &amp; momentum.</h1>
        <p class="hero-lede">Atelier Horizon partners with founders and ambitious teams on identity, product and strategy — design that feels as considered as it looks.</p>
        <div class="hero-actions">
          <a class="button" href="#contact">Get Started <span aria-hidden="true">&#8594;</span></a>
          <a class="text-link" href="#services">Explore services <span aria-hidden="true">&#8595;</span></a>
        </div>
        <div class="social-proof">
          <div class="avatar-stack" aria-hidden="true">
            <span>MK</span><span>JT</span><span>AS</span><span>RB</span>
          </div>
          <p>Trusted by <strong>120+ brands</strong> worldwide</p>
        </div>
      </div>
      <div class="hero-visual">
        <div class="hero-image-frame">
          <img src="https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&amp;fit=crop&amp;w=1200&amp;q=85" alt="Sculptural modern interior with warm wood and soft natural light">
        </div>
        <div
          class="rating-card"
          [class.is-dragging]="isRatingDragging"
          [style.transform]="'translate3d(' + ratingOffsetX + 'px, ' + ratingOffsetY + 'px, 0)'"
          role="group"
          tabindex="0"
          aria-label="Client rating 4.9. Drag to reposition, or use the arrow keys."
          aria-keyshortcuts="ArrowUp ArrowDown ArrowLeft ArrowRight"
          (pointerdown)="startRatingDrag($event)"
          (pointermove)="moveRatingDrag($event)"
          (pointerup)="endRatingDrag()"
          (pointercancel)="endRatingDrag()"
          (lostpointercapture)="endRatingDrag()"
          (keydown)="moveRatingCardWithKeyboard($event)">
          <strong class="rating-score">4.9</strong>
          <div><strong>Client rating</strong><span>Across 120 launches since 2017</span></div>
        </div>
      </div>
    </div>
  </header>

  <section id="about" class="about-section">
    <div class="container about-layout">
      <figure class="about-visual">
        <img src="https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&amp;fit=crop&amp;w=1200&amp;q=85" alt="A light-filled creative studio with a long shared worktable">
        <figcaption>Our atelier in Amsterdam</figcaption>
      </figure>
      <div class="about-copy">
        <p class="eyebrow"><span></span> About the studio</p>
        <h2>A small studio with a <em>deliberate</em> practice.</h2>
        <p class="about-lede">Atelier Horizon exists to give ambitious ideas a form people remember. Since 2017 we have helped 120+ founders and teams turn positioning, product and identity into one coherent story.</p>
        <p class="about-detail">We stay deliberately small: three disciplines, one team, no hand-offs. The people you meet on the first call are the ones drawing, prototyping and shipping your brand.</p>

        <div class="principles">
          <article class="principle">
            <span class="principle-icon" aria-hidden="true">
              <svg viewBox="0 0 32 32"><path d="M3 16s4.8-8 13-8 13 8 13 8-4.8 8-13 8S3 16 3 16Z"/><circle cx="16" cy="16" r="4"/></svg>
            </span>
            <div><h3>Clarity before decoration</h3><p>Every element earns its place. If it does not guide the eye, it goes.</p></div>
          </article>
          <article class="principle">
            <span class="principle-icon" aria-hidden="true">
              <svg viewBox="0 0 32 32"><path d="M12 7h12M8 16h16M12 25h12"/><circle cx="8" cy="7" r="3"/><circle cx="24" cy="16" r="3"/><circle cx="8" cy="25" r="3"/></svg>
            </span>
            <div><h3>Process over guesswork</h3><p>Research, prototypes and honest critique — no lucky stabs in the dark.</p></div>
          </article>
          <article class="principle">
            <span class="principle-icon" aria-hidden="true">
              <svg viewBox="0 0 32 32"><path d="M27.5 11.5c0 7-11.5 15-11.5 15s-11.5-8-11.5-15a6.5 6.5 0 0 1 11.5-4.2 6.5 6.5 0 0 1 11.5 4.2Z"/></svg>
            </span>
            <div><h3>Partners, not vendors</h3><p>We embed with your team and care about the outcome, not the invoice.</p></div>
          </article>
        </div>

        <div class="metrics">
          <div><strong>9+</strong><span>Years of practice</span></div>
          <div><strong>120</strong><span>Projects delivered</span></div>
          <div><strong>14</strong><span>International awards</span></div>
        </div>
      </div>
    </div>
  </section>

  <section id="services" class="services-section">
    <div class="container">
      <div class="services-heading">
        <div>
          <p class="eyebrow"><span></span> What we do</p>
          <h2>Three disciplines, <em>one</em><br>standard.</h2>
        </div>
        <p>Everything a brand needs to launch, grow and outlast trends — delivered by one tight team.</p>
      </div>
      <div class="service-grid">
        <article class="service-card" *ngFor="let service of services">
          <div class="service-card-top">
            <span class="service-icon" aria-hidden="true">
              <svg *ngIf="service.icon === 'identity'" viewBox="0 0 48 48"><path d="m8 8 25 6 7 19-14 8-8-8L8 8Z"/><path d="m18 33 15-19M8 8l19 33M13 18l7 7"/><circle cx="29" cy="21" r="3"/></svg>
              <svg *ngIf="service.icon === 'product'" viewBox="0 0 48 48"><path d="m24 7 18 9-18 9-18-9 18-9Z"/><path d="m6 24 18 9 18-9M6 33l18 9 18-9"/></svg>
              <svg *ngIf="service.icon === 'strategy'" viewBox="0 0 48 48"><circle cx="24" cy="24" r="18"/><path d="m31 17-5 14-9 3 4-12 10-5Z"/><path d="m22 25 4 2"/></svg>
            </span>
            <span class="service-number">{{ service.number }}</span>
          </div>
          <h3>{{ service.title }}</h3>
          <p>{{ service.desc }}</p>
          <a href="#contact" class="service-link">Start a project <span aria-hidden="true">&#8594;</span></a>
        </article>
      </div>
    </div>
  </section>

  <section id="contact" class="contact-section">
    <div class="container contact-layout">
      <div class="contact-copy">
        <p class="eyebrow"><span></span> Contact</p>
        <h2>Let’s make something <em>worth</em> keeping.</h2>
        <p>Tell us where your brand is headed and what is standing in the way. We reply to every message within two working days.</p>
        <div class="contact-details">
          <a class="contact-detail" href="mailto:hello@atelierhorizon.studio">
            <span class="detail-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m4 7 8 6 8-6"/></svg></span>
            <span><strong>Email</strong><small>hello@atelierhorizon.studio</small></span>
          </a>
          <div class="contact-detail">
            <span class="detail-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></svg></span>
            <span><strong>Studio</strong><small>Prinsengracht 402, Amsterdam</small></span>
          </div>
          <div class="contact-detail">
            <span class="detail-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg></span>
            <span><strong>Hours</strong><small>Mon–Fri · 9:00–18:00 CET</small></span>
          </div>
        </div>
      </div>
      <form class="contact-form" (ngSubmit)="onSubmit()" #contactForm="ngForm">
        <div class="form-row">
          <div class="form-group">
            <label for="contact-name">Name</label>
            <input id="contact-name" type="text" [(ngModel)]="contact.name" name="name" required placeholder="Jane Appleseed">
          </div>
          <div class="form-group">
            <label for="contact-email">Email</label>
            <input id="contact-email" type="email" [(ngModel)]="contact.email" name="email" required placeholder="jane@company.com">
          </div>
        </div>
        <div class="form-group">
          <label for="contact-message">Message</label>
          <textarea id="contact-message" [(ngModel)]="contact.message" name="message" rows="4" required placeholder="What are you building, and where do you need help?"></textarea>
        </div>
        <button class="button form-submit" type="submit" [disabled]="!contactForm.form.valid">Send message <span aria-hidden="true">&#8599;</span></button>
        <p *ngIf="submitted" class="success-alert" role="status">Thanks for reaching out. We’ll be in touch within two working days.</p>
      </form>
    </div>
  </section>
</main>

