<section class="chat-widget" aria-label="Studio chat">
  <div *ngIf="isChatOpen" class="chat-panel" id="chat-panel" role="dialog" aria-label="Chat with the Atelier Horizon assistant">
    <header class="chat-header">
      <span class="chat-avatar" aria-hidden="true">Ah</span>
      <div>
        <h2>Studio assistant</h2>
        <p><span class="chat-status" aria-hidden="true"></span> Here to help</p>
      </div>
      <button class="chat-close" type="button" aria-label="Close chat" (click)="isChatOpen = false">&times;</button>
    </header>

    <div class="chat-messages" role="log" aria-live="polite" aria-relevant="additions">
      <div class="chat-message-row" *ngFor="let message of chatMessages" [class.visitor-row]="message.sender === 'visitor'">
        <div class="chat-message" [class.visitor-message]="message.sender === 'visitor'">
          <p>{{ message.text }}</p>
          <a *ngIf="message.actionHref && message.actionLabel" [href]="message.actionHref">{{ message.actionLabel }} <span aria-hidden="true">&#8594;</span></a>
        </div>
      </div>
      <div *ngIf="chatSuggestions.length" class="chat-suggestions" aria-label="Suggested questions">
        <button type="button" *ngFor="let suggestion of chatSuggestions" (click)="sendChatMessage(suggestion)">{{ suggestion }}</button>
      </div>
    </div>

    <form class="chat-form" (ngSubmit)="sendChatMessage()">
      <label class="visually-hidden" for="chat-input">Your message</label>
      <input id="chat-input" type="text" name="chatMessage" [(ngModel)]="chatInput" placeholder="Ask us anything..." autocomplete="off">
      <button type="submit" aria-label="Send message" [disabled]="!chatInput.trim()">
        <span aria-hidden="true">&#8594;</span>
      </button>
    </form>
  </div>

  <button
    class="chat-launcher"
    type="button"
    [attr.aria-expanded]="isChatOpen"
    [attr.aria-controls]="isChatOpen ? 'chat-panel' : null"
    [attr.aria-label]="isChatOpen ? 'Close studio chat' : 'Open studio chat'"
    (click)="isChatOpen = !isChatOpen">
    <svg *ngIf="!isChatOpen" viewBox="0 0 24 24" aria-hidden="true"><path d="M20 11.5a7.5 7.5 0 0 1-7.5 7.5 8 8 0 0 1-3.6-.9L4 20l1.9-4.1A7.5 7.5 0 1 1 20 11.5Z"/><path d="M8.5 11.5h7M8.5 14.5h4"/></svg>
    <span *ngIf="isChatOpen" aria-hidden="true">&times;</span>
  </button>
</section>
